CREATE TABLE public.side_hustles (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  slug text NOT NULL UNIQUE,
  title text NOT NULL,
  summary text NOT NULL,
  category text NOT NULL,
  level text NOT NULL,
  earning_potential text NOT NULL,
  startup_cost text NOT NULL,
  tools text[] NOT NULL DEFAULT '{}',
  first_steps text[] NOT NULL DEFAULT '{}',
  is_free_preview boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now()
);

GRANT SELECT ON public.side_hustles TO anon;
GRANT SELECT ON public.side_hustles TO authenticated;
GRANT ALL ON public.side_hustles TO service_role;

ALTER TABLE public.side_hustles ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Anyone can browse the side hustle library"
ON public.side_hustles FOR SELECT TO anon, authenticated USING (true);

CREATE TABLE public.member_side_hustles (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  side_hustle_id uuid NOT NULL REFERENCES public.side_hustles(id) ON DELETE CASCADE,
  is_favorite boolean NOT NULL DEFAULT false,
  status text NOT NULL DEFAULT 'saved',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (user_id, side_hustle_id)
);

GRANT SELECT, INSERT, UPDATE, DELETE ON public.member_side_hustles TO authenticated;
GRANT ALL ON public.member_side_hustles TO service_role;

ALTER TABLE public.member_side_hustles ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Members manage their own saved ideas"
ON public.member_side_hustles FOR ALL TO authenticated
USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);

CREATE TRIGGER member_side_hustles_set_updated_at
BEFORE UPDATE ON public.member_side_hustles
FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

CREATE INDEX side_hustles_category_idx ON public.side_hustles (category);
CREATE INDEX side_hustles_level_idx ON public.side_hustles (level);
CREATE INDEX member_side_hustles_user_idx ON public.member_side_hustles (user_id);

